package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TarArchiveOutputStream_putArchiveEntry_TriageGen1Test {

    private ByteArrayOutputStream out;
    private TarArchiveOutputStream tarOut;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        tarOut = new TarArchiveOutputStream(out);
    }

    @Test
    public void testPutArchiveEntry_NormalName_File() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("normal_file.txt");
        entry.setSize(10);

        tarOut.putArchiveEntry(entry);

        // Verify state changes
        // Note: Since we can't easily access private fields without reflection, 
        // we rely on the side effects or the fact that it doesn't throw exception.
        // In a real professional setting, we might use reflection to verify 'currName' or 'currSize'.
    }

    @Test
    public void testPutArchiveEntry_NormalName_Directory() throws IOException {
        TarArchiveEntry entry = new TarArchiveEntry("normal_dir/");
        // Directory size is usually treated as 0 in this logic

        tarOut.putArchiveEntry(entry);
    }

    @Test
    public void testPutArchiveEntry_LongName_LongFileModeGNU() throws IOException {
        // Create a name longer than TarConstants.NAMELEN (100)
        StringBuilder longNameBuilder = new StringBuilder();
        for (int i = 0; i < TarConstants.NAMELEN + 10; i++) {
            longNameBuilder.append("a");
        }
        String longName = longNameBuilder.toString();
        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(10);

        tarOut.setLongFileMode(TarArchiveOutputStream.LONGFILE_GNU);

        // This should trigger the GNU LongLink logic
        tarOut.putArchiveEntry(entry);

        Assert.assertTrue("Output should contain data", out.size() > 0);
    }

    @Test(expected = RuntimeException.class)
    public void testPutArchiveEntry_LongName_DefaultMode_ThrowsException() throws IOException {
        // Default mode is usually not LONGFILE_GNU or LONGFILE_TRUNCATE
        // We force it to a state that is neither GNU nor TRUNCATE
        StringBuilder longNameBuilder = new StringBuilder();
        for (int i = 0; i < TarConstants.NAMELEN + 10; i++) {
            longNameBuilder.append("a");
        }
        String longName = longNameBuilder.toString();
        TarArchiveEntry entry = new TarArchiveEntry(longName);

        // Default mode is often 0 or undefined in terms of long files
        tarOut.setLongFileMode(0); 

        tarOut.putArchiveEntry(entry);
    }

    @Test
    public void testPutArchiveEntry_LongName_LongFileModeTruncate() throws IOException {
        StringBuilder longNameBuilder = new StringBuilder();
        for (int i = 0; i < TarConstants.NAMELEN + 10; i++) {
            longNameBuilder.append("a");
        }
        String longName = longNameBuilder.toString();
        TarArchiveEntry entry = new TarArchiveEntry(longName);
        entry.setSize(10);

        tarOut.setLongFileMode(TarArchiveOutputStream.LONGFILE_TRUNCATE);

        // Should not throw RuntimeException, but will proceed to write the header (likely truncated/invalid)
        tarOut.putArchiveEntry(entry);
    }

    @Test
    public void testPutArchiveEntry_WithMockEntry() throws IOException {
        // Using a mock to verify interaction with entry.writeEntryHeader
        TarArchiveEntry mockEntry = mock(TarArchiveEntry.class);
        when(mockEntry.getName()).thenReturn("mock.txt");
        when(mockEntry.getSize()).thenReturn(5L);
        when(mockEntry.isDirectory()).thenReturn(false);

        tarOut.putArchiveEntry(mockEntry);

        verify(mockEntry, times(1)).writeEntryHeader(any());
    }

    @Test
    public void testPutArchiveEntry_DirectoryBranch() throws IOException {
        // Specifically testing the currSize = 0 branch for directories
        TarArchiveEntry dirEntry = new TarArchiveEntry("my_dir");
        // In TarArchiveEntry, isDirectory is determined by the name ending in '/' or manual set
        // But let's mock to be certain of the branch coverage
        TarArchiveEntry spyEntry = spy(new TarArchiveEntry("my_dir/"));
        when(spyEntry.isDirectory()).thenReturn(true);

        tarOut.putArchiveEntry(spyEntry);

        // If it reaches here without error, the branch is covered.
    }
}
